concepts.code:
-- Optimistic: the WHERE is the check
UPDATE docs
SET body = 'v4 text', version = version + 1
WHERE id = 42 AND version = 3      -- the version this client read
RETURNING version;                  -- no row back = conflict (or missing)

-- Pessimistic: hold the row for the length of the transaction
BEGIN;
SELECT body, version FROM docs WHERE id = 42 FOR UPDATE;
-- ... compute the new body in the app, quickly ...
UPDATE docs SET body = 'v4 text', version = version + 1 WHERE id = 42;
COMMIT;

-- Fail fast if someone holds the row
SELECT * FROM tickets WHERE id = 7 FOR UPDATE NOWAIT;
-- ERROR: could not obtain lock on row in relation "tickets"   (55P03)

-- Cap every lock wait in this transaction
BEGIN;
SET LOCAL lock_timeout = '2s';
UPDATE tickets SET status = 'closed' WHERE id = 7;
COMMIT;

-- Queue: take whatever is free, skip what is locked
SELECT id FROM jobs
WHERE status = 'queued'
ORDER BY created_at, id
LIMIT 10
FOR UPDATE SKIP LOCKED;

-- Transfer 30 from account 2 to account 1, deadlock-free:
BEGIN;
SELECT id FROM accounts
WHERE id IN (1, 2)
ORDER BY id              -- always lock the lower id first
FOR UPDATE;
UPDATE accounts SET balance = balance - 30 WHERE id = 2;
UPDATE accounts SET balance = balance + 30 WHERE id = 1;
COMMIT;
-- On 40P01 (or 40001 under SERIALIZABLE): ROLLBACK and retry the whole thing

-- Run the nightly billing job on at most one worker
BEGIN;
SELECT pg_try_advisory_xact_lock(424242) AS got_it;
-- got_it = false: another worker is running it; COMMIT and exit
-- got_it = true:  do the work; the lock is released at COMMIT
COMMIT;

-- Per-tenant: two-int form (job type, tenant id)
SELECT pg_advisory_xact_lock(7, 1001);

-- Migration session: give up quickly rather than block the app
SET lock_timeout = '3s';
ALTER TABLE orders ADD COLUMN gift_note text;   -- metadata only, but ACCESS EXCLUSIVE
-- on 55P03: wait a bit and retry

-- Build an index without blocking writes (not inside BEGIN ... COMMIT)
CREATE INDEX CONCURRENTLY orders_customer_idx ON orders (customer_id);

-- Who is waiting on whom?
SELECT pid, wait_event_type, pg_blocking_pids(pid) AS blocked_by, left(query, 60)
FROM pg_stat_activity
WHERE wait_event_type = 'Lock';

exercises.schema:
CREATE TABLE stock (
  sku text PRIMARY KEY,
  qty int  NOT NULL
);
CREATE TABLE cart (
  sku  text PRIMARY KEY,
  want int  NOT NULL CHECK (want > 0)
);

CREATE TABLE docs (
  id         int  PRIMARY KEY,
  body       text NOT NULL,
  version    int  NOT NULL,
  updated_by text
);
CREATE TABLE edits (
  doc_id       int  PRIMARY KEY,
  base_version int  NOT NULL,
  new_body     text NOT NULL,
  editor       text NOT NULL
);
CREATE TABLE conflicts (
  doc_id          int NOT NULL,
  base_version    int NOT NULL,
  current_version int
);

